args.script:
extends RefCounted
func execute(scene_tree: SceneTree) -> Variant:
 var test = scene_tree.current_scene.get_meta("rail_test")
 var result = test.result()
 for i in 60:
  result = test.advance()
  if result.done: break
 return result

